{"python":"import re, math

PDF='2022_281692_KUUSANMAKI_SUPPL.pdf'

def cell_parts(c):
    if isinstance(c, dict):
        return str(c.get('value','')), c.get('x0'), c.get('ref')
    return str(c), None, None

def cluster_xs(vals, tol=8.0):
    xs=sorted(vals)
    groups=[]
    for x in xs:
        if not groups or abs(x-groups[-1][-1])>tol:
            groups.append([x])
        else:
            groups[-1].append(x)
    centers=[sum(g)/len(g) for g in groups]
    def nearest(x):
        return min(range(len(centers)), key=lambda i: abs(x-centers[i]))
    return centers, nearest

def auc_higher(scores, truth):
    pairs=sorted(zip(scores,truth), key=lambda z:z[0])
    ranks={}
    i=0
    while i<len(pairs):
        j=i+1
        while j<len(pairs) and pairs[j][0]==pairs[i][0]:
            j+=1
        avg=(i+1+j)/2.0
        for k in range(i,j):
            ranks[k]=avg
        i=j
    pos=sum(truth)
    neg=len(truth)-pos
    rank_sum=sum(ranks[k] for k,(_,y) in enumerate(pairs) if y==1)
    return (rank_sum-pos*(pos+1)/2.0)/(pos*neg)

def truth_value(t):
    t=t.strip().upper()
    if t in ('CR','CRI','MLFS','CR/CRI','CR / CRI') or 'CR/CRI' in t:
        return 1
    if t in ('RD','PD') or 'RESISTANT DISEASE' in t or 'REFRACTORY DISEASE' in t:
        return 0
    return None

candidates=[]
for sh in list(tables[PDF].keys()):
    geo=tables[PDF][sh].rows
    words=[]
    for r,row in enumerate(geo):
        for c in row:
            text,x,ref=cell_parts(c)
            if text is not None and str(text).strip() and x is not None:
                words.append({'r':r,'x':float(x),'text':str(text).strip(),'ref':ref})
    if not words:
        continue
    centers,nearest=cluster_xs([w['x'] for w in words])
    for w in words:
        w['col']=nearest(w['x'])
    headers=[' '.join(w['text'] for w in words if w['col']==col and w['r']<14).lower()
               for col in range(len(centers))]
    label_counts=[0]*len(centers)
    for w in words:
        if truth_value(w['text']) is not None:
            label_counts[w['col']]+=1
    for sc,h in enumerate(headers):
        fc_cm=((('fc' in h or 'flow' in h) and ('cm' in h or 'conditioned' in h))
               and 'ctg' not in h and 'bulk' not in h)
        if not fc_cm:
            continue
        for oc,count in enumerate(label_counts):
            if count<10:
                continue
            byrow={}
            for w in words:
                byrow.setdefault(w['r'],[]).append(w)
            records=[]
            for r,ws in byrow.items():
                sw=[w for w in ws if w['col']==sc]
                ow=[w for w in ws if w['col']==oc]
                if not sw or not ow:
                    continue
                try:
                    score=float(sw[-1]['text'])
                except Exception:
                    m=re.search(r'-?\d+(?:\.\d+)?', sw[-1]['text'])
                    if not m:
                        continue
                    score=float(m.group())
                y=truth_value(ow[-1]['text'])
                if y is None:
                    continue
                pid=None
                for w in ws:
                    if re.fullmatch(r'\d{4}', w['text']):
                        pid=w['text']; break
                records.append({'id':pid or (sh+':R'+str(r+1)),
                                'score':{'ref':sw[-1]['ref']},
                                'truth':{'ref':ow[-1]['ref']},
                                '_score':score,'y':y})
            if len(records)>=20:
                a=auc_higher([x['_score'] for x in records],[x['y'] for x in records])
                candidates.append((abs(len(records)-37), -len(records), abs(a-.82), sh, sc, oc, len(records), a, records, headers[sc], headers[oc]))

print('CANDIDATES')
for c in candidates:
    print(c[3], 'score_col',c[4],'outcome_col',c[5],'n',c[6],'auc',c[7], 'header=',c[9][:120], 'outheader=',c[10][:120])

records=[]
computed=None
if candidates:
